script:
const body = root_element.querySelector('.pd-dues-body');
const esc = (v) => frappe.utils.escape_html(v == null ? '' : String(v));

root_element.querySelector('.pd-dues-all').addEventListener('click', (e) => {
	e.preventDefault();
	frappe.set_route('query-report', 'Debt Facility Summary');
});

frappe.xcall('panorama_debt.api.dashboard.get_upcoming_dues', { limit: 10 })
	.then((rows) => {
		if (!rows || !rows.length) {
			body.innerHTML = '<p class="text-muted">' +
				__('Nothing is due. Every active facility is either settled or has no schedule yet.') + '</p>';
			return;
		}

		const today = frappe.datetime.get_today();
		const lines = rows.map((r) => {
			const overdue = r.next_due_date && r.next_due_date < today;
			const date = esc(frappe.datetime.str_to_user(r.next_due_date));
			return '<tr>' +
				'<td>' + frappe.utils.get_form_link('Debt Facility', r.name, true) + '</td>' +
				'<td>' + esc(r.loan_provider) + '</td>' +
				'<td class="' + (overdue ? 'overdue' : '') + '">' + date +
					(overdue ? '<span class="tag">' + __('Overdue') + '</span>' : '') + '</td>' +
				'<td class="amount">' + format_currency(r.next_due_amount, r.currency) + '</td>' +
				'</tr>';
		}).join('');

		body.innerHTML = '<table><thead><tr>' +
			'<th>' + __('Loan ID') + '</th><th>' + __('Loan Provider') + '</th>' +
			'<th>' + __('Next Due Date') + '</th><th class="amount">' + __('Next Due Amount') + '</th>' +
			'</tr></thead><tbody>' + lines + '</tbody></table>';
	})
	.catch(() => {
		body.innerHTML = '<p class="text-muted">' + __('Could not load upcoming dues.') + '</p>';
	});

style:
.pd-dues { font-size: var(--text-md); }
.pd-dues-head { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 8px; }
.pd-dues-title { font-weight: 600; }
.pd-dues-all { font-size: var(--text-sm); cursor: pointer; }
/* Tables are the one thing allowed to scroll sideways on a phone. */
.pd-dues-body { overflow-x: auto; }
.pd-dues table { width: 100%; border-collapse: collapse; }
.pd-dues th, .pd-dues td { padding: 6px 8px; border-bottom: 1px solid var(--border-color); text-align: left; white-space: nowrap; }
.pd-dues th { font-weight: 500; color: var(--text-muted); font-size: var(--text-sm); }
.pd-dues td.amount, .pd-dues th.amount { text-align: right; }
.pd-dues .overdue { color: var(--red-500); font-weight: 600; }
.pd-dues .tag { background: var(--red-100); color: var(--red-600); border-radius: 4px; padding: 1px 6px; font-size: var(--text-xs); margin-left: 6px; }
